-- DAWALINK Premium subscription groundwork
CREATE TABLE IF NOT EXISTS app_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, trial_started_at timestamptz NOT NULL DEFAULT now(), trial_ends_at timestamptz NOT NULL DEFAULT (now() + interval '30 days'), status text NOT NULL DEFAULT 'TRIAL' CHECK (status IN ('TRIAL','ACTIVE','PAST_DUE','CANCELED','EXPIRED')), provider text, provider_customer_id text, provider_subscription_id text UNIQUE, current_period_start timestamptz, current_period_end timestamptz, cancel_at_period_end boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS app_subscriptions_status_trial_end_idx ON app_subscriptions(status, trial_ends_at);
